import { initFirebase, register, login, logout, sendPasswordReset, loadProfile, saveProfile, subscribeProfile, createGroup, joinGroup, subscribeGroup, saveGroup, updateMemberSummary, leaveGroup, archiveAndDeleteProfile, exportProfileBackup, firebaseEnabled } from './firebase-service.js';
import { defaultGroup, emptyLiveSession, award, evaluateDailyCompletion, levelFromXp, dailyChallenges, renderAvatar, isAvatarItemUnlocked, buyAvatarItem, openChest, buyShopItem, resetProfileForTesting, slugify } from './gamification.js';
import { DOMAINS, TOPICS, STARTER_DECKS, GAME_QUESTIONS, AVATAR_ITEMS, SHOP_ITEMS, HOMEWORK_IDEAS, OFFICIAL_LINKS } from './content.js';
import { todayISO, formatDate, formatShort, monthDayYear, addDays, daysBetween, generateRoadmap, groupByWeek, currentRoadmapDay, progressSummary, domainCompletion, catchUpPlan, adaptiveMessage, isPaused, isStudyDay, weekStartSunday, weekEndSaturday } from './planner.js';
import { downloadIcs, recurrenceRuleForDays } from './calendar.js';

const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app');
const state={ user:null, profile:null, group:null, activeView:'home', groupAttached:null, clockTick:null, timerTick:null, calendarMonth:null, deckScope:'Public', noteScope:'Personal', game:null, renderedOnce:false };
const NAV=[
  ['home','Command Center','home'], ['room','Study Room','room'], ['plan','Study Plan','plan'], ['practice','Practice Log','practice'],
  ['tools','Study Tools','tools'], ['guild','Guild','guild'], ['calendar','Calendar','calendar'], ['notes','Notebook','notes'], ['rewards','Rewards','rewards'], ['profile','Profile','settings']
];
const WEEK_COLORS=['#7C4DFF','#00A7FF','#18C29C','#FFB347','#FF5C8A','#9B5CFF','#14B8A6','#F97316','#22C55E','#38BDF8','#C084FC','#F43F5E'];

init();
async function init(){
  renderBoot('Connecting To Firebase...');
  await initFirebase(handleAuth,msg=>console.log(msg));
  if(!firebaseEnabled()) renderFirebaseSetup();
  window.addEventListener('resize',()=>document.body.classList.toggle('mobile-size',innerWidth<760));
}
async function handleAuth(user){
  state.user=user;
  if(!user){ state.profile=null; state.group=null; stopTimer(); stopClock(); renderLogin(); return; }
  renderBoot('Loading Your Quest Profile...');
  try{
    const profile=await loadProfile(user.uid);
    migrateProfile(profile);
    state.profile=profile;
    applyTheme();
    startClock();
    subscribeProfile(user.uid,p=>{
      const oldView=state.activeView;
      state.profile=p; migrateProfile(state.profile); state.activeView=oldView; applyTheme();
      if(p.activeGroupId) attachGroup(p.activeGroupId);
      renderApp();
    });
    if(state.profile.activeGroupId) attachGroup(state.profile.activeGroupId);
    renderApp();
    if(!state.profile.onboarding?.completed) showOnboardingWizard();
  }catch(e){ toast(friendly(e),'error'); renderLogin(); }
}
function migrateProfile(p){
  p.progress=p.progress||{};
  ['xpLog','qaeLogs','mistakes','flashcards','homework','calendarEvents','notes','chests','purchases','weekendLogs','decks','resetBackups'].forEach(k=>p.progress[k]=Array.isArray(p.progress[k])?p.progress[k]:[]);
  p.progress.dailyChallenges=p.progress.dailyChallenges||{};
  p.progress.dayCompletion=p.progress.dayCompletion||{};
  p.progress.lessonTasks=p.progress.lessonTasks||{};
  p.stats=p.stats||{}; p.stats.coins=p.stats.coins||0; p.stats.xp=p.stats.xp||0; p.stats.streakFreezes=p.stats.streakFreezes??2;
  p.avatar=p.avatar||{}; p.avatar.owned=p.avatar.owned||['#7c4dff','#00a7ff','none','round','clipboard','focused'];
  p.preferences=p.preferences||{}; p.preferences.theme=p.preferences.theme||'dark'; p.preferences.timezone=p.preferences.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'America/New_York';
  p.studyPlan=p.studyPlan||{}; p.studyPlan.startDate=p.studyPlan.startDate||todayISO(p); p.studyPlan.examDate=p.studyPlan.examDate||addDays(todayISO(p),110); p.studyPlan.sessionTime=p.studyPlan.sessionTime||'07:00'; p.studyPlan.sessionDuration=Number(p.studyPlan.sessionDuration||60); p.studyPlan.dailyQaeGoal=Number(p.studyPlan.dailyQaeGoal||10); p.studyPlan.sessionDays=p.studyPlan.sessionDays||[1,2,3,4,5]; p.studyPlan.pauseBlocks=p.studyPlan.pauseBlocks||[];
  p.onboarding=p.onboarding||{completed:false}; p.groups=p.groups||[];
}
function attachGroup(id){
  if(!id || state.groupAttached===id) return;
  state.groupAttached=id;
  subscribeGroup(id,g=>{ state.group=g; migrateGroup(g); renderApp(); });
}
function migrateGroup(g){ if(!g)return; g.memberSummaries=g.memberSummaries||{}; g.sharedCalendar=g.sharedCalendar||[]; g.notes=g.notes||[]; g.decks=g.decks||[]; g.sessionHistory=g.sessionHistory||[]; g.liveSession=g.liveSession||emptyLiveSession(state.profile||{}); g.settings=g.settings||{}; }
function renderBoot(msg){ app.className='boot-screen'; app.innerHTML=`<div class="boot-card"><img src="assets/mascots/ollie.svg" alt="Ollie"><h1>ControlQuest Studio</h1><p>${esc(msg)}</p></div>`; }
function renderFirebaseSetup(){ app.className='auth-shell'; app.innerHTML=`<section class="auth-card"><div class="auth-visual"><img src="assets/mascots/ollie.svg" alt="Ollie"><p class="eyebrow">Setup Needed</p><h1>Almost Ready</h1><p>Firebase is not enabled in <code>config/firebase-config.js</code>. Keep your working Firebase config when upgrading packages.</p></div><div class="auth-form"><h2>Setup Checklist</h2><ol class="setup-list"><li>Paste your Firebase web config values.</li><li>Set <code>enabled: true</code>.</li><li>Enable Email/Password Auth.</li><li>Create Firestore and publish the rules.</li></ol></div></section>`; }
function renderLogin(){
  app.className='auth-shell';
  app.innerHTML=`<section class="auth-card"><div class="auth-visual"><img src="assets/mascots/ollie.svg" alt="Ollie"><p class="eyebrow">Gamified CISA Prep</p><h1>ControlQuest Studio</h1><p>Turn CISA prep into daily quests, live study rooms, guild accountability, streaks, coins, flashcards, and arcade practice.</p><div class="mini-proof"><span>Firebase Sync</span><span>Study Guilds</span><span>Quest XP</span><span>Adaptive Roadmap</span></div></div><div class="auth-form"><div class="tab-row"><button class="tab active" data-auth-tab="login">Log In</button><button class="tab" data-auth-tab="create">Create Account</button></div><form id="loginForm" class="auth-tab active"><h2>Welcome Back</h2><label>Email<input type="email" id="loginEmail" autocomplete="email" required></label><label>Password<input type="password" id="loginPassword" autocomplete="current-password" required></label><button class="primary-button full" type="submit">Log In</button><button class="text-button" id="resetPasswordBtn" type="button">Send Password Reset</button><p class="helper">Your browser stays signed in using Firebase Auth persistence.</p></form><form id="createForm" class="auth-tab"><h2>Create Your Quest Profile</h2><label>Display Name<input id="createName" required></label><label>Email<input type="email" id="createEmail" required></label><label>Password<input type="password" id="createPassword" minlength="6" required></label><button class="primary-button full" type="submit">Create Account</button></form></div></section>`;
  $$('[data-auth-tab]').forEach(b=>b.onclick=()=>switchAuthTab(b.dataset.authTab));
  $('#loginForm').onsubmit=async e=>{e.preventDefault();try{await login($('#loginEmail').value.trim(),$('#loginPassword').value);toast('Logged In.');}catch(err){toast(friendly(err),'error')}};
  $('#createForm').onsubmit=async e=>{e.preventDefault();try{await register($('#createEmail').value.trim(),$('#createPassword').value,$('#createName').value.trim());toast('Account Created.');}catch(err){toast(friendly(err),'error')}};
  $('#resetPasswordBtn').onclick=async()=>{const email=$('#loginEmail').value.trim(); if(!email)return toast('Enter Your Email First.','warn'); await sendPasswordReset(email); toast('Password Reset Sent.');};
}
function switchAuthTab(tab){$$('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab)); $$('.auth-tab').forEach(el=>el.classList.toggle('active',el.id.startsWith(tab)));}
function renderApp(){
  if(!state.profile)return;
  const p=state.profile,lvl=levelFromXp(p.stats.xp||0),sum=progressSummary(p);
  app.className='app-shell';
  app.innerHTML=`<aside class="sidebar"><div class="brand"><img src="assets/icons/logo-mark.svg" alt="ControlQuest"><div><p class="eyebrow">ControlQuest</p><h1>Studio</h1></div></div><button class="mobile-close ghost-button" id="closeNavBtn">Close</button><nav class="nav-list" id="navList">${NAV.map(n=>nav(n[0],n[1],n[2])).join('')}</nav><div class="side-player">${renderAvatar(p,'small')}<div><strong>${esc(p.displayName)}</strong><span>Level ${lvl.level} · ${p.stats.streak||0}-Day Streak</span></div></div></aside><main class="main"><header class="topbar"><button class="hamburger icon-button" id="openNavBtn">${icon('menu')}</button><div><p class="eyebrow">${state.group?esc(state.group.name):'Solo Quest Mode'}</p><h2>${pageTitle()}</h2></div><div class="top-actions"><div class="clock-chip" id="clockChip"><strong>--:--</strong><small>${esc(p.preferences.timezone)}</small></div><select id="themeSelect" class="ghost-button" aria-label="Theme"><option value="dark">Theme: Dark</option><option value="light">Theme: Light</option></select><button class="ghost-button" id="helpBtn">Help</button><button class="ghost-button" id="logoutBtn">Log Out</button></div></header><section class="status-strip" data-tour="status-strip">${statTile('xp',p.stats.xp||0,'XP')}${statTile('coin',p.stats.coins||0,'Audit Coins')}${statTile('streak',p.stats.streak||0,'Streak')}${statTile('freeze',p.stats.streakFreezes||0,'Freezes')}${statTile('roadmap',sum.percent+'%','Roadmap')}</section><div id="viewMount"></div></main>`;
  $('#themeSelect').value=p.preferences.theme==='light'?'light':'dark';
  bindShell(); renderView(); updateClock();
}
function nav(v,l,i){return `<button class="nav-btn ${state.activeView===v?'active':''}" data-view="${v}">${appIcon(i)}<span>${l}</span></button>`;}
function statTile(i,n,l){return `<div class="stat-tile"><span class="icon-art icon-${i}">${svgIcon(i)}</span><div><span>${esc(n)}</span><small>${l}</small></div></div>`;}
function bindShell(){
  $$('.nav-btn').forEach(b=>b.onclick=()=>{ state.activeView=b.dataset.view; document.body.classList.remove('nav-open'); renderApp(); });
  $('#themeSelect').onchange=async e=>{state.profile.preferences.theme=e.target.value; applyTheme(); await saveAll(); renderApp();};
  $('#logoutBtn').onclick=()=>logout(); $('#helpBtn').onclick=()=>showPageTour(state.activeView); $('#openNavBtn')?.addEventListener('click',()=>document.body.classList.add('nav-open')); $('#closeNavBtn')?.addEventListener('click',()=>document.body.classList.remove('nav-open'));
}
function renderView(){ const m=$('#viewMount'); const views={home:renderHome,room:renderRoom,plan:renderPlan,practice:renderPractice,tools:renderTools,guild:renderGuild,calendar:renderCalendar,notes:renderNotes,rewards:renderRewards,profile:renderProfile}; (views[state.activeView]||renderHome)(m); }
function pageTitle(){ return Object.fromEntries(NAV.map(n=>[n[0],n[1]]))[state.activeView]||'ControlQuest'; }
function startClock(){ stopClock(); state.clockTick=setInterval(updateClock,1000); }
function stopClock(){ if(state.clockTick) clearInterval(state.clockTick); }
function updateClock(){ const chip=$('#clockChip'); if(!chip||!state.profile)return; const tz=state.profile.preferences.timezone; const now=new Date(); chip.querySelector('strong').textContent=now.toLocaleTimeString([], {hour:'numeric',minute:'2-digit',second:'2-digit',timeZone:tz}); chip.querySelector('small').textContent=`${now.toLocaleDateString([], {weekday:'short',month:'short',day:'numeric',timeZone:tz})} · ${tz}`; }

function renderHome(m){
  const p=state.profile, day=currentRoadmapDay(p), lvl=levelFromXp(p.stats.xp||0), challenges=dailyChallenges(p,todayISO(p)), doneMap=p.progress.dailyChallenges[todayISO(p)]||{}, catchups=catchUpPlan(p), recent=(p.progress.xpLog||[]).slice(0,5);
  m.innerHTML=`<div class="dashboard-grid"><section class="panel hero" data-tour="home-hero"><div><p class="eyebrow">Today’s Mission</p><h2>${esc(day?.topic?.title||'Start Your Quest')}</h2><p>${esc(day?.topic?.focus||'Build momentum with one focused study action at a time.')}</p><div class="hero-actions"><button class="primary-button" data-go="room">Open Study Room</button><button class="secondary-button" data-go="plan">View Study Plan</button></div></div><div class="hero-avatar">${renderAvatar(p)}<div class="speech">${esc(adaptiveMessage(p))}</div></div></section><section class="panel" data-tour="xp-box"><div class="section-head"><div><p class="eyebrow">Progress Engine</p><h3>Level ${lvl.level}</h3></div><span class="status-pill">${lvl.progress}% To Next Level</span></div><div class="progress"><span style="width:${lvl.progress}%"></span></div><div class="two-col"><div class="soft"><div class="stat-tile">${svgIcon('coin')}<div><span>${p.stats.coins||0}</span><small>Audit Coins</small></div></div></div><div class="soft"><div class="stat-tile">${svgIcon('freeze')}<div><span>${p.stats.streakFreezes||0}</span><small>Auto Freezes</small></div></div></div></div><div class="section-head" style="margin-top:16px"><h4>Recent Activity</h4><button class="text-button small" data-go="rewards">Full Activity</button></div><div class="activity-mini">${recent.length?recent.map(activityRow).join(''):'<p class="helper">No XP activity yet. Complete a quest to start the log.</p>'}</div></section><section class="panel daily-panel" data-tour="daily-quests"><div class="section-head"><div><p class="eyebrow">Required For Streak</p><h3>Daily Quests</h3><p class="helper">Complete all three daily quests on scheduled study days. This protects your streak and prevents fake progress.</p></div><span class="status-pill">${Math.min(3,Object.values(doneMap).filter(x=>x?.done).length)} / 3 Complete</span></div><div class="daily-quests">${challenges.map(ch=>dailyQuestCard(ch,doneMap[ch.key])).join('')}</div></section><section class="panel"><div class="section-head"><div><p class="eyebrow">Group Pulse</p><h3>${state.group?'Guild Snapshot':'No Guild Yet'}</h3></div>${appIcon('guild')}</div>${renderGroupPulse()}</section><section class="panel"><div class="section-head"><div><p class="eyebrow">Catch-Up Compass</p><h3>${catchups.length?'Action Needed':'All Clear'}</h3></div>${appIcon('plan')}</div>${catchups.length?catchups.slice(0,3).map(c=>`<div class="list-card"><h4>${esc(c.title)}</h4><p>${esc(c.detail)}</p><button class="secondary-button small" data-catchup="${escAttr(c.id)}">Complete Catch-Up</button></div>`).join(''):'<p class="helper">No overdue homework or missed study days. Keep stacking small wins.</p>'}</section></div>`;
  bindGo(); $$('.quest-card button[data-complete-quest]').forEach(b=>b.onclick=()=>completeDailyQuest(b.dataset.completeQuest)); $$('[data-catchup]').forEach(b=>b.onclick=()=>completeCatchup(b.dataset.catchup));
}
function dailyQuestCard(ch,done){ return `<article class="quest-card ${done?'complete':''}"><span class="icon-art">${svgIcon(ch.icon||'quest')}</span><h4>${esc(ch.title)}</h4><p>${esc(ch.detail)}</p><strong>${ch.xp} XP · ${ch.coins} Coins</strong>${done?'<span class="done-pill">Complete</span>':`<label class="sr-only">Evidence</label>${ch.requiresEvidence?'<input placeholder="Optional Evidence / Notes" data-evidence="'+escAttr(ch.key)+'">':''}<button class="primary-button full" data-complete-quest="${escAttr(ch.key)}">Complete Quest</button>`}</article>`; }
function renderGroupPulse(){ if(!state.group)return `<p class="helper">Create or join a guild to see shared accountability, member streaks, and session momentum.</p><button class="secondary-button" data-go="guild">Go To Guild</button>`; const members=Object.values(state.group.memberSummaries||{}); return `<div class="member-stack">${members.slice(0,4).map(mem=>`<div class="member-mini">${renderMiniAvatar(mem.avatar)}<div><strong>${esc(mem.displayName)}</strong><em>Level ${mem.level} · ${mem.streak}-Day Streak · ${mem.totalQae} QAE</em></div><span class="status-pill">${mem.completedDays||0} Days</span></div>`).join('')}</div>`; }
function activityRow(a){ return `<div class="activity-row"><span class="icon-art ${a.coins?'icon-coin':'icon-xp'}">${svgIcon(a.source||'xp')}</span><div><strong>${esc(titleCase(a.reason||'Quest Reward'))}</strong><small>${new Date(a.at||Date.now()).toLocaleString()}</small></div><div class="activity-delta"><span class="xp">+${a.xp||0} XP</span><br>+${a.coins||0}</div></div>`; }
async function completeDailyQuest(key){ const p=state.profile, date=todayISO(p), ch=dailyChallenges(p,date).find(x=>x.key===key); if(!ch)return; const map=p.progress.dailyChallenges[date]=p.progress.dailyChallenges[date]||{}; if(map[key]?.done)return toast('That Daily Quest Is Already Complete.','warn'); const evidence=$(`[data-evidence="${key}"]`)?.value||''; map[key]={done:true,evidence,completedAt:new Date().toISOString(),xp:ch.xp,coins:ch.coins}; const result=awardWithPop({xp:ch.xp,coins:ch.coins,reason:`Daily Quest: ${ch.title}`,source:'Daily Quest',meta:{key}}); maybeChest('bronze',`Daily Quest: ${ch.title}`,0.28); evaluateDailyCompletion(p,date); await saveAll(); renderApp(); }
async function completeCatchup(id){ const p=state.profile; const item=catchUpPlan(p).find(c=>c.id===id); if(!item)return; if(id.startsWith('homework-')){ const hw=p.progress.homework.find(h=>`homework-${h.id}`===id); if(hw){hw.complete=true;hw.completedAt=new Date().toISOString();} } else if(id.startsWith('catch-')){ const date=id.replace('catch-',''); p.progress.dayCompletion[date]=p.progress.dayCompletion[date]||{}; p.progress.dayCompletion[date].status='Complete Late'; p.progress.dayCompletion[date].completedAt=new Date().toISOString(); }
  awardWithPop({xp:Math.round(item.xp*.75),coins:Math.round(item.coins*.75),reason:`Catch-Up Complete: ${item.title}`,source:'Catch-Up'}); await saveAll(); renderApp(); }

function renderRoom(m){
  if(!state.group){ m.innerHTML=`<section class="panel"><p class="eyebrow">Live Sync Requires A Guild</p><h2>Create Or Join A Study Guild First</h2><p class="helper">The Study Room syncs timer, checklist, check-ins, shared notes, and session history through your active guild.</p><button class="primary-button" data-go="guild">Go To Guild</button></section>`; bindGo(); return; }
  const s=state.group.liveSession||emptyLiveSession(state.profile), day=currentRoadmapDay(state.profile), elapsed=timerSeconds(s), total=(s.durationMinutes||60)*60, remain=Math.max(0,total-elapsed), percent=Math.min(100,Math.round(elapsed/Math.max(1,total)*100));
  const steps=sessionSteps(day);
  m.innerHTML=`<section class="panel live-room" data-tour="room-timer"><div class="live-hero"><div><div class="timer-orb" id="timerOrb" style="--timer-progress:${percent}%"><div><strong id="timerText">${fmtTime(remain)}</strong><span>${percent}% Complete</span></div></div><div class="timer-bar"><span id="timerBar" style="width:${percent}%"></span></div></div><div><p class="eyebrow">Live Study Room</p><h2>${esc(s.title||'Live Study Session')}</h2><p class="helper">This room syncs across everyone in the guild. Use it for the 7–8 AM session or any extra study block.</p><div class="three-col"><label>Start Time<input type="time" id="sessionTime" value="${state.group.schedule?.time||state.profile.studyPlan.sessionTime}"></label><label>Duration Minutes<input type="number" id="sessionDuration" min="15" max="240" value="${s.durationMinutes||60}"></label><label>Session Title<input id="sessionTitle" value="${escAttr(s.title||'Live Study Session')}"></label></div><div class="button-row"><button class="primary-button" id="startTimerBtn">${s.active?'Pause Timer':'Start Timer'}</button><button class="secondary-button" id="resetTimerBtn">Reset Timer</button><button class="secondary-button" id="completeSessionBtn">Complete Session</button><button class="ghost-button" id="saveSessionSettingsBtn">Save Settings</button></div></div></div></section><section class="two-col" style="margin-top:16px"><div class="panel" data-tour="session-flow"><div class="section-head"><div><p class="eyebrow">Shared Session Flow</p><h3>Today’s Plan</h3><p class="helper">Check these off together. They save live to the guild session.</p></div></div><div class="soft"><h4>${esc(day?.topic?.title||'Study Session')}</h4><p class="helper">${esc(day?.topic?.focus||'Focus on the highest-value topic for today.')}</p>${resourceLinks(day?.topic?.links||['qae','cisaOutline'])}</div><div class="checklist" style="margin-top:12px">${steps.map((st,i)=>checkRow(st,s.checklist?.[st.id])).join('')}</div></div><div class="panel" data-tour="room-notes"><div class="section-head"><div><p class="eyebrow">Shared Notes</p><h3>Guild Session Notes</h3><p class="helper">These notes save to the live session. Use “Save To Notebook” to store them permanently.</p></div></div><textarea id="sharedSessionNotes" placeholder="Capture decisions, confusing topics, links, and tomorrow’s homework...">${esc(s.notes||'')}</textarea><div class="button-row"><button class="primary-button" id="saveSessionNotesBtn">Save Shared Notes</button><button class="secondary-button" id="sessionNotesToNotebookBtn">Save To Notebook</button></div><hr style="border-color:var(--line);margin:18px 0"><h3>Homework Builder</h3><p class="helper">Pick rotating suggestions or create your own. Homework due date defaults to the next study day.</p><div id="homeworkOptions" class="homework-options">${homeworkOptions(day).map((h,i)=>homeworkOption(h,i)).join('')}</div><div class="two-col"><label>Custom Homework Title<input id="customHwTitle" placeholder="Example: Review missed BCP questions"></label><label>Due Date<input type="date" id="customHwDue" value="${nextStudyDate()}"></label></div><label>Custom Details<textarea id="customHwDetail" placeholder="What exactly should you do?"></textarea></label><button class="secondary-button" id="addCustomHwBtn">Add Custom Homework</button><h4>Open Homework</h4><div class="list" id="homeworkList">${renderHomeworkList()}</div></div></section>`;
  bindGo(); startTimerTicker();
  $('#startTimerBtn').onclick=toggleTimer; $('#resetTimerBtn').onclick=resetTimer; $('#completeSessionBtn').onclick=completeLiveSession; $('#saveSessionSettingsBtn').onclick=saveSessionSettings;
  $$('.check-row input').forEach(cb=>cb.onchange=()=>toggleSessionCheck(cb.dataset.check,cb.checked));
  $('#saveSessionNotesBtn').onclick=saveSessionNotes; $('#sessionNotesToNotebookBtn').onclick=saveSessionNotesToNotebook;
  $$('.homework-option').forEach(b=>b.onclick=()=>addSuggestedHomework(Number(b.dataset.hwIndex)));
  $('#addCustomHwBtn').onclick=addCustomHomework;
  $$('.complete-homework').forEach(b=>b.onclick=()=>completeHomework(b.dataset.id));
}
function sessionSteps(day){ const tasks=day?.topic?.tasks?.slice(0,4)||[]; return [{id:'warmup',title:'Warm-Up Recall',detail:'Say what you remember from yesterday and what feels unclear.'},...tasks.map((t,i)=>({id:`task-${i}`,title:t,detail:i===0?'Use a video, visual map, or official QAE reference where helpful.':'Talk through the logic out loud together.'})),{id:'wrap',title:'Error Log + Homework',detail:'Log misses, assign homework, and close with tomorrow’s focus.'}]; }
function checkRow(st,done){return `<label class="check-row"><input type="checkbox" data-check="${escAttr(st.id)}" ${done?'checked':''}><div><strong>${esc(st.title)}</strong><small>${esc(st.detail)}</small></div></label>`;}
function resourceLinks(keys){ return `<div class="button-row">${keys.map(k=>OFFICIAL_LINKS[k]?`<a class="secondary-button small" target="_blank" rel="noopener" href="${OFFICIAL_LINKS[k]}">${linkLabel(k)}</a>`:'').join('')}</div>`; }
function linkLabel(k){return {qae:'Open ISACA QAE',cisaOutline:'Exam Outline',cisaOverview:'CISA Overview',udemy:'Open Udemy'}[k]||'Open Link';}
function homeworkOptions(day){ const base=(day?.topic?.homework||[]).map((h,i)=>({title:h,detail:'Recommended from today’s lesson.',type:'Lesson',xp:30,coins:8})); const seed=(new Date().getDate()+base.length)%HOMEWORK_IDEAS.length; return [...base,...HOMEWORK_IDEAS.slice(seed),...HOMEWORK_IDEAS.slice(0,seed)].slice(0,6); }
function homeworkOption(h,i){ return `<button class="homework-option" data-hw-index="${i}"><strong>${esc(h.title)}</strong><p>${esc(h.detail)}</p><small>${esc(h.type)} · ${h.xp||25} XP · ${h.coins||6} Coins</small></button>`; }
function nextStudyDate(){ let d=addDays(todayISO(state.profile),1), guard=0; while(guard++<14 && !isStudyDay(state.profile,d)) d=addDays(d,1); return d; }
function renderHomeworkList(){ const open=(state.profile.progress.homework||[]).filter(h=>!h.complete).slice(0,8); return open.length?open.map(h=>`<div class="list-card"><h4>${esc(h.title)}</h4><p>${esc(h.detail||'')}</p><p class="helper">Due ${h.dueDate?formatDate(h.dueDate):'No Due Date'} · Added ${new Date(h.createdAt||Date.now()).toLocaleString()}</p><button class="primary-button small complete-homework" data-id="${h.id}">Mark Complete</button></div>`).join(''):'<p class="helper">No open homework yet.</p>'; }
async function toggleTimer(){ const g=state.group,s=g.liveSession||emptyLiveSession(state.profile); if(s.active){ s.accumulatedSeconds=timerSeconds(s); s.active=false; s.pausedAt=new Date().toISOString(); } else { s.active=true; s.startedAt=new Date().toISOString(); s.pausedAt=null; } s.updatedAt=new Date().toISOString(); g.liveSession=s; await saveAll({group:true}); renderApp(); }
async function resetTimer(){ const s=state.group.liveSession||emptyLiveSession(state.profile); s.active=false;s.startedAt=null;s.accumulatedSeconds=0;s.updatedAt=new Date().toISOString(); state.group.liveSession=s; await saveAll({group:true}); renderApp(); }
async function saveSessionSettings(){ const s=state.group.liveSession||emptyLiveSession(state.profile); const dur=validateNumber('#sessionDuration',15,240,'Duration Must Be 15–240 Minutes.'); if(!dur)return; s.durationMinutes=dur; s.title=$('#sessionTitle').value.trim()||'Live Study Session'; state.group.schedule=state.group.schedule||{}; state.group.schedule.time=$('#sessionTime').value||'07:00'; state.group.schedule.duration=dur; state.group.liveSession=s; state.profile.studyPlan.sessionTime=state.group.schedule.time; state.profile.studyPlan.sessionDuration=dur; await saveAll({group:true}); toast('Session Settings Saved.'); }
async function toggleSessionCheck(id,checked){ const s=state.group.liveSession||emptyLiveSession(state.profile); s.checklist=s.checklist||{}; s.checklist[id]=checked; s.updatedAt=new Date().toISOString(); state.group.liveSession=s; await saveAll({group:true,quiet:true}); }
async function saveSessionNotes(){ const s=state.group.liveSession||emptyLiveSession(state.profile); s.notes=$('#sharedSessionNotes').value; s.updatedAt=new Date().toISOString(); state.group.liveSession=s; await saveAll({group:true}); toast('Shared Notes Saved.'); }
async function saveSessionNotesToNotebook(){ await saveSessionNotes(); const body=$('#sharedSessionNotes').value.trim(); if(!body)return toast('Add Notes Before Saving To Notebook.','warn'); addNoteObject({title:`Session Notes - ${formatDate(todayISO(state.profile))}`,body,scope:'Guild',source:'Study Room'}); await saveAll({group:true}); renderApp(); }
async function completeLiveSession(){ const g=state.group, s=g.liveSession||emptyLiveSession(state.profile); const minutes=Math.round(timerSeconds(s)/60)||Number(s.durationMinutes||60); g.sessionHistory=g.sessionHistory||[]; g.sessionHistory.unshift({id:crypto.randomUUID(),title:s.title||'Live Study Session',date:todayISO(state.profile),minutes,completedBy:state.profile.uid,completedAt:new Date().toISOString(),checklist:s.checklist||{}}); g.liveSession=emptyLiveSession(state.profile); state.profile.stats.totalSessions=(state.profile.stats.totalSessions||0)+1; awardWithPop({xp:65,coins:18,reason:`Completed Live Session: ${minutes} Minutes`,source:'Live Study Room'}); await saveAll({group:true}); renderApp(); }
function addSuggestedHomework(i){ const h=homeworkOptions(currentRoadmapDay(state.profile))[i]; if(!h)return; addHomework(h); renderRoom($('#viewMount')); }
function addCustomHomework(){ const title=$('#customHwTitle').value.trim(); if(!title)return toast('Add A Homework Title.','warn'); addHomework({title,detail:$('#customHwDetail').value.trim(),dueDate:$('#customHwDue').value,type:'Custom',xp:30,coins:8}); renderRoom($('#viewMount')); }
function addHomework(h){ state.profile.progress.homework.unshift({id:crypto.randomUUID(),title:h.title,detail:h.detail||'',type:h.type||'Homework',dueDate:h.dueDate||nextStudyDate(),xp:h.xp||30,coins:h.coins||8,source:'Study Room',createdAt:new Date().toISOString(),complete:false}); toast('Homework Added.'); saveAll(); }
async function completeHomework(id){ const h=state.profile.progress.homework.find(x=>x.id===id); if(!h)return; h.complete=true; h.completedAt=new Date().toISOString(); const late=h.dueDate && h.dueDate<todayISO(state.profile); awardWithPop({xp:late?Math.round((h.xp||30)*.7):(h.xp||30),coins:late?Math.round((h.coins||8)*.7):(h.coins||8),reason:`Homework Complete: ${h.title}`,source:'Homework'}); await saveAll(); renderApp(); }

function renderPlan(m){
  const p=state.profile, sum=progressSummary(p), weeks=groupByWeek(generateRoadmap(p));
  m.innerHTML=`<section class="panel" data-tour="plan-settings"><div class="section-head"><div><p class="eyebrow">Adaptive Study Plan</p><h2>Roadmap Controls</h2><p class="helper">Your roadmap shifts around exam date changes, pause blocks, and bonus weekend sessions.</p></div><span class="status-pill">${sum.done} / ${sum.total} Study Days Complete</span></div><div class="grid-4"><label>Start Date<input type="date" id="planStart" value="${p.studyPlan.startDate}"></label><label>Exam Date<input type="date" id="planExam" value="${p.studyPlan.examDate}"></label><label>Daily QAE Goal<input type="number" id="planQaeGoal" min="1" max="150" value="${p.studyPlan.dailyQaeGoal}"></label><label>Timezone<select id="planTimezone"><option>${esc(p.preferences.timezone)}</option><option>America/New_York</option><option>America/Chicago</option><option>America/Denver</option><option>America/Los_Angeles</option></select></label></div><div class="button-row"><button class="primary-button" id="savePlanBtn">Save And Recalculate</button><button class="secondary-button" id="addPauseBtn">Add Pause Day / Block</button><button class="secondary-button" id="addWeekendBtn">Add Bonus Study Session</button></div></section><section class="panel" style="margin-top:16px"><div class="section-head"><div><p class="eyebrow">Pause Blocks</p><h3>Protected Breaks</h3></div></div><div class="list">${(p.studyPlan.pauseBlocks||[]).length?p.studyPlan.pauseBlocks.map((b,i)=>`<div class="list-card"><h4>${formatDate(b.start)} – ${formatDate(b.end)}</h4><p>${esc(b.reason||'Pause Block')}</p><button class="danger-button small" data-delete-pause="${i}">Delete Pause Block</button></div>`).join(''):'<p class="helper">No pause blocks yet.</p>'}</div></section><section class="roadmap-weeks" style="margin-top:16px" data-tour="roadmap-weeks">${weeks.map(w=>renderWeek(w)).join('')}</section>`;
  $('#savePlanBtn').onclick=savePlan; $('#addPauseBtn').onclick=openPauseModal; $('#addWeekendBtn').onclick=openEventModal;
  $$('[data-delete-pause]').forEach(b=>b.onclick=async()=>{ state.profile.studyPlan.pauseBlocks.splice(Number(b.dataset.deletePause),1); await saveAll(); renderApp(); });
  $$('.day-card').forEach(card=>card.onclick=e=>{ if(e.target.closest('button,input,a'))return; card.classList.toggle('opened'); });
  $$('.lesson-task-check').forEach(cb=>cb.onchange=()=>toggleLessonTask(cb.dataset.date,Number(cb.dataset.idx),cb.checked));
}
function renderWeek(w){ const color=WEEK_COLORS[(w.week-1)%WEEK_COLORS.length]; const done=w.days.filter(d=>['Complete','Complete Late','Done'].includes(d.status)).length; return `<article class="week-card" style="--week-color:${color}"><div class="week-head"><div><h3>Week ${w.week} · ${formatShort(w.start)} – ${formatShort(w.end)}</h3><p class="helper">${done} / ${w.days.filter(d=>d.type==='study').length} Required Study Days Complete</p></div><span class="icon-art" style="background:linear-gradient(135deg,${color},var(--primary2))">${svgIcon('roadmap')}</span></div><div class="week-days">${w.days.map(d=>renderDay(d,color)).join('')}</div></article>`; }
function renderDay(d,color){ const tasks=d.topic?.tasks||[], rec=state.profile.progress.lessonTasks?.[d.date]||{}; return `<div class="day-card ${d.type.toLowerCase()}" style="--week-color:${color}"><div class="day-date"><strong>${formatShort(d.date)}</strong><span class="status-pill ${d.status.toLowerCase().replaceAll(' ','-')}">${esc(d.status)}</span></div><div class="day-title">${esc(d.topic?.title||d.title||'Rest')}</div><div class="drop-hint">${svgIcon('chevron')} Click For Details</div>${d.events?.length?`<div>${d.events.map(e=>`<span class="event-pill event-${e.scope||'personal'}">${esc(e.title)}</span>`).join('')}</div>`:''}<div class="day-details"><p class="helper">${esc(d.topic?.focus||'')}</p>${resourceLinks(d.topic?.links||[])}<div class="list">${tasks.length?tasks.map((t,i)=>`<label class="check-row"><input class="lesson-task-check" type="checkbox" data-date="${d.date}" data-idx="${i}" ${rec[i]?'checked':''}><div><strong>Task ${i+1}</strong><small>${esc(t)}</small></div></label>`).join(''):'<p class="helper">No required lesson tasks for this day.</p>'}</div></div></div>`; }
async function toggleLessonTask(date,idx,checked){ const p=state.profile; p.progress.lessonTasks[date]=p.progress.lessonTasks[date]||{}; p.progress.lessonTasks[date][idx]=checked; const day=generateRoadmap(p).find(d=>d.date===date); const count=Object.values(p.progress.lessonTasks[date]).filter(Boolean).length; if(day?.topic?.tasks?.length && count>=day.topic.tasks.length){ p.progress.dayCompletion[date]=p.progress.dayCompletion[date]||{}; if(!p.progress.dayCompletion[date].lessonComplete){ p.progress.dayCompletion[date].lessonComplete=true; awardWithPop({xp:55,coins:15,reason:`Lesson Complete: ${day.topic.title}`,source:'Roadmap'}); } }
  await saveAll(); }
function savePlan(){ const q=validateNumber('#planQaeGoal',1,150,'Daily QAE Goal Must Be 1–150.'); if(!q)return; state.profile.studyPlan.startDate=$('#planStart').value; state.profile.studyPlan.examDate=$('#planExam').value; state.profile.studyPlan.dailyQaeGoal=q; state.profile.preferences.timezone=$('#planTimezone').value; saveAll().then(()=>{toast('Study Plan Recalculated.'); renderApp();}); }
function openPauseModal(){ modal('Add Pause Day Or Block',`<p class="helper">Pause blocks protect the streak and push required roadmap work forward.</p><div class="two-col"><label>Start Date<input type="date" id="pauseStart" value="${todayISO(state.profile)}"></label><label>End Date<input type="date" id="pauseEnd" value="${todayISO(state.profile)}"></label></div><label>Reason<input id="pauseReason" placeholder="Vacation, Client Travel, PTO, Busy Week"></label>`,async()=>{ const start=$('#pauseStart').value,end=$('#pauseEnd').value; if(!start||!end||end<start)return toast('Enter A Valid Date Range.','error'); state.profile.studyPlan.pauseBlocks.push({id:crypto.randomUUID(),start,end,reason:$('#pauseReason').value||'Pause Block'}); await saveAll(); renderApp(); }); }

function renderPractice(m){
  const p=state.profile;
  m.innerHTML=`<section class="analysis-grid"><div class="panel" data-tour="qae-log"><div class="section-head"><div><p class="eyebrow">QAE Arena</p><h2>Practice Log</h2><p class="helper">Use this after official QAE blocks. Correct answers cannot exceed total questions, and every log can be edited later.</p></div><a class="secondary-button" href="${OFFICIAL_LINKS.qae}" target="_blank" rel="noopener">Open ISACA QAE</a></div><div class="grid-4"><label>Domain<select id="qaeDomain">${DOMAINS.map(d=>`<option value="${d.id}">${d.short}: ${d.title}</option>`).join('')}</select></label><label>Topic<select id="qaeTopic"></select></label><label>Questions<input type="number" min="1" max="150" id="qaeTotal" value="10"></label><label>Correct<input type="number" min="0" max="150" id="qaeCorrect" value="0"></label></div><label>Notes<textarea id="qaeNotes" placeholder="What did you miss? What was the CISA logic? What do you need to retest?"></textarea></label><button class="primary-button" id="addQaeBtn">Log QAE Block</button><div class="chart-wrap" style="margin-top:16px"><canvas id="qaeChart"></canvas></div></div><div class="panel"><p class="eyebrow">QAE Summary</p>${renderQaeSummary()}</div></section><section class="two-col" style="margin-top:16px"><div class="panel" data-tour="mistake-forge"><p class="eyebrow">Mistake Forge</p><h2>Convert Misses Into Study Fuel</h2><p class="helper">Use this for wrong or guessed questions. The goal is not to copy questions; it is to capture the concept and the correct CISA logic.</p><label>Domain<select id="mistakeDomain">${DOMAINS.map(d=>`<option value="${d.id}">${d.short}: ${d.title}</option>`).join('')}</select></label><label>Topic / Trap<input id="mistakeTopic" placeholder="Example: Auditor recommended remediation too early"></label><label>Correct CISA Logic<textarea id="mistakeLogic" placeholder="The auditor should validate cause, impact, and evidence before recommending corrective action."></textarea></label><label>Retest Date<input type="date" id="mistakeRetest" value="${addDays(todayISO(p),3)}"></label><button class="primary-button" id="addMistakeBtn">Add Mistake</button></div><div class="panel"><div class="section-head"><h3>Open Mistakes</h3><span class="status-pill">${(p.progress.mistakes||[]).filter(x=>x.status!=='Reviewed').length} Open</span></div><div class="list">${(p.progress.mistakes||[]).slice(0,12).map(renderMistake).join('')||'<p class="helper">No mistakes logged yet.</p>'}</div></div></section><section class="panel" style="margin-top:16px"><div class="section-head"><h3>QAE Logs</h3><span class="status-pill">${p.progress.qaeLogs.length} Blocks</span></div><div class="list">${p.progress.qaeLogs.slice(0,12).map(renderQaeLog).join('')||'<p class="helper">No QAE logs yet.</p>'}</div></section>`;
  populateQaeTopics(); $('#qaeDomain').onchange=populateQaeTopics; $('#addQaeBtn').onclick=addQaeLog; $('#addMistakeBtn').onclick=addMistake; $$('.edit-qae').forEach(b=>b.onclick=()=>editQae(b.dataset.id)); $$('.delete-qae').forEach(b=>b.onclick=()=>deleteQae(b.dataset.id)); $$('.edit-mistake').forEach(b=>b.onclick=()=>editMistake(b.dataset.id)); $$('.review-mistake').forEach(b=>b.onclick=()=>reviewMistake(b.dataset.id)); $$('.delete-mistake').forEach(b=>b.onclick=()=>deleteMistake(b.dataset.id)); drawQaeChart();
}
function populateQaeTopics(){ const d=$('#qaeDomain')?.value||'D1'; const opts=TOPICS.filter(t=>t.domain===d).map(t=>`<option>${esc(t.title)}</option>`).join(''); if($('#qaeTopic')) $('#qaeTopic').innerHTML=opts||'<option>Mixed Review</option>'; }
function renderQaeSummary(){ const logs=state.profile.progress.qaeLogs||[]; const total=logs.reduce((a,l)=>a+(l.total||0),0), correct=logs.reduce((a,l)=>a+(l.correct||0),0); return `<div class="list"><div class="stat-tile">${svgIcon('qae')}<div><span>${total}</span><small>Total Questions Logged</small></div></div><div class="stat-tile">${svgIcon('target')}<div><span>${total?Math.round(correct/total*100):0}%</span><small>Overall Accuracy</small></div></div>${DOMAINS.filter(d=>d.id!=='MIX').map(d=>{ const dl=logs.filter(l=>l.domain===d.id); const t=dl.reduce((a,l)=>a+l.total,0),c=dl.reduce((a,l)=>a+l.correct,0); return `<div class="list-card"><h4>${d.short}</h4><div class="progress"><span style="width:${t?Math.round(c/t*100):0}%"></span></div><p>${t?Math.round(c/t*100):0}% Accuracy · ${t} Questions</p></div>`}).join('')}</div>`; }
function renderQaeLog(l){ return `<div class="list-card"><h4>${esc(l.domain)} · ${esc(l.topic||'Practice Block')}</h4><p>${l.correct} / ${l.total} Correct · ${Math.round(l.correct/l.total*100)}% · ${new Date(l.createdAt).toLocaleString()}</p><p class="helper">${esc(l.notes||'')}</p><div class="button-row"><button class="secondary-button small edit-qae" data-id="${l.id}">Edit</button><button class="danger-button small delete-qae" data-id="${l.id}">Delete</button></div></div>`; }
function renderMistake(x){ return `<div class="list-card"><h4>${esc(x.topic)}</h4><p>${esc(x.logic)}</p><p class="helper">${esc(x.domain||'')} · Retest ${x.retest?formatDate(x.retest):'Not Set'} · ${titleCase(x.status||'Open')}</p><div class="button-row"><button class="secondary-button small edit-mistake" data-id="${x.id}">Edit</button><button class="primary-button small review-mistake" data-id="${x.id}">Mark Reviewed</button><button class="danger-button small delete-mistake" data-id="${x.id}">Delete</button></div></div>`; }
async function addQaeLog(){ const total=validateNumber('#qaeTotal',1,150,'Questions Must Be 1–150.'); const correct=validateNumber('#qaeCorrect',0,150,'Correct Must Be 0–150.'); if(total===false||correct===false)return; if(correct>total)return fieldError('#qaeCorrect','Correct Cannot Exceed Total Questions.'); const log={id:crypto.randomUUID(),domain:$('#qaeDomain').value,topic:$('#qaeTopic').value,total,correct,notes:$('#qaeNotes').value.trim(),createdAt:new Date().toISOString()}; state.profile.progress.qaeLogs.unshift(log); state.profile.stats.totalQae=(state.profile.stats.totalQae||0)+total; const pct=correct/total; awardWithPop({xp:Math.round(20+total*2+pct*30),coins:Math.round(5+total/2+pct*10),reason:`QAE Block Logged: ${correct}/${total}`,source:'QAE'}); if(pct>=.8) maybeChest('silver','80%+ QAE Block',.7); await saveAll(); renderApp(); }
function editQae(id){ const l=state.profile.progress.qaeLogs.find(x=>x.id===id); if(!l)return; modal('Edit QAE Log',`<label>Correct<input type="number" id="editQaeCorrect" value="${l.correct}"></label><label>Total<input type="number" id="editQaeTotal" value="${l.total}"></label><label>Notes<textarea id="editQaeNotes">${esc(l.notes||'')}</textarea></label>`,async()=>{ const t=Number($('#editQaeTotal').value), c=Number($('#editQaeCorrect').value); if(c>t||t<1)return toast('Correct Must Be Less Than Or Equal To Total.','error'); Object.assign(l,{total:t,correct:c,notes:$('#editQaeNotes').value}); await saveAll(); renderApp(); }); }
async function deleteQae(id){ if(!confirm('Delete This QAE Log?'))return; state.profile.progress.qaeLogs=state.profile.progress.qaeLogs.filter(x=>x.id!==id); await saveAll(); renderApp(); }
async function addMistake(){ const topic=$('#mistakeTopic').value.trim(), logic=$('#mistakeLogic').value.trim(); if(!topic||!logic)return toast('Add Both Topic And Correct Logic.','warn'); state.profile.progress.mistakes.unshift({id:crypto.randomUUID(),domain:$('#mistakeDomain').value,topic,logic,retest:$('#mistakeRetest').value,status:'Open',createdAt:new Date().toISOString()}); state.profile.stats.totalMistakes=(state.profile.stats.totalMistakes||0)+1; awardWithPop({xp:35,coins:10,reason:`Mistake Forged: ${topic}`,source:'Mistake Forge'}); await saveAll(); renderApp(); }
function editMistake(id){ const x=state.profile.progress.mistakes.find(m=>m.id===id); if(!x)return; modal('Edit Mistake',`<label>Topic<input id="editMistakeTopic" value="${escAttr(x.topic)}"></label><label>Logic<textarea id="editMistakeLogic">${esc(x.logic)}</textarea></label><label>Retest Date<input type="date" id="editMistakeRetest" value="${x.retest||''}"></label>`,async()=>{ x.topic=$('#editMistakeTopic').value; x.logic=$('#editMistakeLogic').value; x.retest=$('#editMistakeRetest').value; await saveAll(); renderApp(); }); }
async function reviewMistake(id){ const x=state.profile.progress.mistakes.find(m=>m.id===id); if(!x)return; x.status='Reviewed'; x.reviewedAt=new Date().toISOString(); awardWithPop({xp:25,coins:8,reason:`Mistake Reviewed: ${x.topic}`,source:'Mistake Review'}); await saveAll(); renderApp(); }
async function deleteMistake(id){ if(!confirm('Delete This Mistake?'))return; state.profile.progress.mistakes=state.profile.progress.mistakes.filter(x=>x.id!==id); await saveAll(); renderApp(); }
function drawQaeChart(){ const c=$('#qaeChart'); if(!c)return; const ctx=c.getContext('2d'), logs=[...(state.profile.progress.qaeLogs||[])].slice(0,12).reverse(); c.width=c.clientWidth*devicePixelRatio; c.height=c.clientHeight*devicePixelRatio; ctx.scale(devicePixelRatio,devicePixelRatio); const w=c.clientWidth,h=c.clientHeight; ctx.clearRect(0,0,w,h); ctx.strokeStyle='rgba(255,255,255,.16)'; ctx.lineWidth=1; for(let i=0;i<5;i++){ const y=20+i*(h-40)/4; ctx.beginPath();ctx.moveTo(32,y);ctx.lineTo(w-10,y);ctx.stroke(); } if(!logs.length){ctx.fillStyle='#9fb0d0';ctx.fillText('No QAE Logs Yet',40,40);return;} ctx.strokeStyle='#00c2ff';ctx.lineWidth=3;ctx.beginPath(); logs.forEach((l,i)=>{ const x=40+i*(w-60)/Math.max(1,logs.length-1), y=h-20-(l.correct/l.total)*(h-50); i?ctx.lineTo(x,y):ctx.moveTo(x,y); }); ctx.stroke(); logs.forEach((l,i)=>{ const x=40+i*(w-60)/Math.max(1,logs.length-1), y=h-20-(l.correct/l.total)*(h-50); ctx.fillStyle='#7c4dff';ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill(); }); }

function renderTools(m){
  m.innerHTML=`<section class="two-col"><div class="panel" data-tour="memory-decks"><div class="section-head"><div><p class="eyebrow">Memory Deck</p><h2>Flashcards</h2><p class="helper">Use public starter decks, guild decks, or your own personal decks. Study in-app or export TSV for Quizlet.</p></div><button class="primary-button" id="newDeckBtn">Create Deck</button></div><div class="scope-tabs">${['Public','Guild','Personal'].map(s=>`<button class="secondary-button small ${state.deckScope===s?'active':''}" data-deck-scope="${s}">${s} Decks</button>`).join('')}</div><div class="deck-grid">${getDecks(state.deckScope).map(renderDeck).join('')||'<p class="helper">No decks in this scope yet.</p>'}</div></div><div class="panel" data-tour="arcade"><p class="eyebrow">ControlQuest Arcade</p><h2>Study Games</h2><p class="helper">Games award XP and coins when you answer correctly. More visual games are baked into this page.</p><div class="grid-4"><button class="secondary-button" data-game="blitz">Best / First Blitz</button><button class="secondary-button" data-game="match">Memory Match</button><button class="secondary-button" data-game="sort">Control Sorter</button><button class="secondary-button" data-game="race">Avatar Sprint</button></div><div id="gameMount" style="margin-top:16px"></div></div></section>`;
  $$('[data-deck-scope]').forEach(b=>b.onclick=()=>{state.deckScope=b.dataset.deckScope;renderApp();}); $('#newDeckBtn').onclick=()=>openDeckEditor(); $$('.study-deck').forEach(b=>b.onclick=()=>studyDeck(b.dataset.id,b.dataset.scope)); $$('.export-deck').forEach(b=>b.onclick=()=>exportDeck(b.dataset.id,b.dataset.scope)); $$('.edit-deck').forEach(b=>b.onclick=()=>openDeckEditor(b.dataset.id,b.dataset.scope)); $$('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));
}
function getDecks(scope){ if(scope==='Public')return STARTER_DECKS; if(scope==='Guild')return state.group?.decks||[]; return state.profile.progress.decks||[]; }
function renderDeck(d){ return `<article class="deck-card"><span class="icon-art">${svgIcon('cards')}</span><h3>${esc(d.title)}</h3><p>${esc(d.description||`${d.cards?.length||0} Cards`)}</p><p class="helper">${esc(d.domain||'Custom')} · ${d.cards?.length||0} Cards · ${titleCase(d.scope||state.deckScope)}</p><div class="button-row"><button class="primary-button small study-deck" data-id="${d.id}" data-scope="${d.scope||state.deckScope}">Study</button><button class="secondary-button small export-deck" data-id="${d.id}" data-scope="${d.scope||state.deckScope}">Export TSV</button>${(d.scope!=='public'&&state.deckScope!=='Public')?`<button class="secondary-button small edit-deck" data-id="${d.id}" data-scope="${d.scope||state.deckScope}">Edit</button>`:''}</div></article>`; }
function findDeck(id,scope){ return getDecks(scope==='public'?'Public':titleCase(scope)).find(d=>d.id===id) || STARTER_DECKS.find(d=>d.id===id); }
function studyDeck(id,scope){ const d=findDeck(id,scope); if(!d)return; let idx=0; const show=()=>modal(`Study Deck: ${d.title}`,`<div class="study-card"><p class="eyebrow">Card ${idx+1} / ${d.cards.length}</p><h3>${esc(d.cards[idx][0])}</h3><details><summary class="primary-button">Show Answer</summary><p>${esc(d.cards[idx][1])}</p></details></div>`,()=>{awardWithPop({xp:8,coins:2,reason:`Reviewed Card: ${d.title}`,source:'Memory Deck'}); idx=(idx+1)%d.cards.length; if(idx!==0)show(); else saveAll();},idx===d.cards.length-1?'Finish + XP':'Next Card'); show(); }
function exportDeck(id,scope){ const d=findDeck(id,scope); const text=(d.cards||[]).map(c=>`${c[0]}\t${c[1]}`).join('\n'); downloadText(`${slugify(d.title)}.tsv`,text); }
function openDeckEditor(id=null,scope='Personal'){ const d=id?findDeck(id,scope):{id:crypto.randomUUID(),title:'',description:'',domain:'D1',scope:'personal',cards:[]}; const cardText=(d.cards||[]).map(c=>`${c[0]} | ${c[1]}`).join('\n'); modal(id?'Edit Deck':'Create Deck',`<label>Deck Title<input id="deckEditTitle" value="${escAttr(d.title)}"></label><label>Description<textarea id="deckEditDescription">${esc(d.description||'')}</textarea></label><div class="two-col"><label>Scope<select id="deckEditScope"><option value="personal">Personal</option><option value="guild">Guild</option></select></label><label>Domain<select id="deckEditDomain">${DOMAINS.map(x=>`<option value="${x.id}">${x.short}</option>`).join('')}</select></label></div><label>Cards<textarea id="deckEditCards" placeholder="Term | Definition, one per line">${esc(cardText)}</textarea></label>`,async()=>{ const nd={...d,title:$('#deckEditTitle').value||'Untitled Deck',description:$('#deckEditDescription').value,scope:$('#deckEditScope').value,domain:$('#deckEditDomain').value,cards:$('#deckEditCards').value.split('\n').map(line=>line.split('|').map(x=>x.trim())).filter(x=>x[0]&&x[1])}; if(nd.scope==='guild'){ if(!state.group)return toast('Join A Guild First.','warn'); state.group.decks=state.group.decks||[]; const i=state.group.decks.findIndex(x=>x.id===nd.id); i>=0?state.group.decks[i]=nd:state.group.decks.unshift(nd); await saveAll({group:true}); } else { const i=state.profile.progress.decks.findIndex(x=>x.id===nd.id); i>=0?state.profile.progress.decks[i]=nd:state.profile.progress.decks.unshift(nd); await saveAll(); } renderApp(); }); }
function startGame(mode){ if(mode==='blitz')return gameBlitz(); if(mode==='match')return gameMatch(); if(mode==='sort')return gameSort(); if(mode==='race')return gameRace(); }
function gameBlitz(){ const q=pick(GAME_QUESTIONS.filter(q=>q.mode==='bestFirst')); $('#gameMount').innerHTML=`<div class="soft"><h3>${esc(q.prompt)}</h3><div class="list">${q.options.map((o,i)=>`<button class="secondary-button answer-btn" data-ok="${i===q.answer}">${esc(o)}</button>`).join('')}</div></div>`; $$('.answer-btn').forEach(b=>b.onclick=()=>gameAnswer(b.dataset.ok==='true',q.explain)); }
function gameMatch(){ const pairs=GAME_QUESTIONS.filter(q=>q.mode==='termMatch').slice(0,6); const cards=shuffle([...pairs.map((p,i)=>({id:i,text:p.term,type:'term'})),...pairs.map((p,i)=>({id:i,text:p.answer,type:'answer'}))]); let first=null,matched=new Set(); $('#gameMount').innerHTML=`<div class="memory-board">${cards.map((c,i)=>`<button class="memory-card" data-i="${i}">ControlQuest</button>`).join('')}</div>`; $$('.memory-card').forEach(btn=>btn.onclick=()=>{ const i=Number(btn.dataset.i), card=cards[i]; if(matched.has(i)||btn.classList.contains('flipped'))return; btn.textContent=card.text; btn.classList.add('flipped'); if(first===null){first=i;return;} const ok=cards[first].id===card.id&&cards[first].type!==card.type; if(ok){matched.add(first);matched.add(i); $$('.memory-card')[first].classList.add('matched'); btn.classList.add('matched'); awardWithPop({xp:12,coins:3,reason:'Memory Match Pair',source:'Arcade'}); if(matched.size===cards.length){awardWithPop({xp:45,coins:15,reason:'Memory Match Complete',source:'Arcade'}); saveAll();} } else setTimeout(()=>{$$('.memory-card')[first]?.classList.remove('flipped');$$('.memory-card')[first].textContent='ControlQuest';btn.classList.remove('flipped');btn.textContent='ControlQuest';},700); first=null; }); }
function gameSort(){ const q=pick(GAME_QUESTIONS.filter(q=>q.mode==='sort')); $('#gameMount').innerHTML=`<div class="soft"><h3>Sort This Control</h3><p>${esc(q.item)}</p><div class="three-col">${['Preventive','Detective','Corrective / Recovery'].map(b=>`<button class="secondary-button answer-btn" data-ok="${b===q.bucket}">${b}</button>`).join('')}</div></div>`; $$('.answer-btn').forEach(b=>b.onclick=()=>gameAnswer(b.dataset.ok==='true',`Correct Bucket: ${q.bucket}`)); }
function gameRace(){ const qs=shuffle(GAME_QUESTIONS.filter(q=>q.mode==='bestFirst')).slice(0,5); state.game={mode:'race',i:0,score:0,qs}; renderRaceQuestion(); }
function renderRaceQuestion(){ const g=state.game,q=g.qs[g.i]; const pct=Math.round(g.score/5*86); $('#gameMount').innerHTML=`<div class="race-track"><div class="race-lane"><div class="race-avatar" style="left:${pct}%">${renderAvatar(state.profile,'tiny')}</div></div><h3>Question ${g.i+1} / 5</h3><p>${esc(q.prompt)}</p><div class="list">${q.options.map((o,i)=>`<button class="secondary-button answer-btn" data-ok="${i===q.answer}">${esc(o)}</button>`).join('')}</div></div>`; $$('.answer-btn').forEach(b=>b.onclick=()=>{ const ok=b.dataset.ok==='true'; if(ok)g.score++; if(g.i>=4){ const xp=30+g.score*18, coins=8+g.score*6; awardWithPop({xp,coins,reason:`Avatar Sprint Finished: ${g.score}/5`,source:'Arcade'}); saveAll(); $('#gameMount').innerHTML=`<div class="soft"><h3>Race Complete</h3><p>You scored ${g.score}/5.</p><button class="primary-button" data-game="race">Race Again</button></div>`; $('[data-game="race"]').onclick=()=>gameRace(); } else { g.i++; renderRaceQuestion(); } }); }
function gameAnswer(ok,msg){ if(ok){ state.profile.stats.arcadeWins=(state.profile.stats.arcadeWins||0)+1; awardWithPop({xp:35,coins:10,reason:'Arcade Win',source:'Arcade'}); celebrate('Correct.'); saveAll(); startGame('blitz'); } else toast(`Not Quite. ${msg}`,'warn'); }

function renderGuild(m){
  const g=state.group, members=Object.values(g?.memberSummaries||{}), minutes=(g?.sessionHistory||[]).reduce((a,s)=>a+(s.minutes||0),0);
  m.innerHTML=`<section class="two-col"><div class="panel" data-tour="guild-setup"><p class="eyebrow">Study Guild</p><h2>${g?esc(g.name):'Create Or Join A Guild'}</h2>${g?`<p class="helper">Group ID: <code>${g.id}</code> · Join Code: <code>${g.joinCode}</code></p><div class="button-row"><button class="secondary-button" id="copyJoinBtn">Copy Join Info</button><button class="danger-button" id="leaveGuildBtn">Leave Guild</button></div><label>Guild Name<input id="guildName" value="${escAttr(g.name)}"></label><label>Guild Icon<input type="file" id="guildIcon" accept="image/*"></label><button class="primary-button" id="saveGuildBtn">Save Guild Settings</button>`:`<label>New Guild Name<input id="newGuildName" placeholder="Example: Ty & Comply Guild"></label><button class="primary-button" id="createGuildBtn">Create Guild</button><hr style="border-color:var(--line)"><label>Group ID<input id="joinGroupId"></label><label>Join Code<input id="joinCode"></label><button class="secondary-button" id="joinGuildBtn">Join Guild</button>`}</div><div class="panel"><p class="eyebrow">Guild Metrics</p><div class="grid-4"><div class="stat-tile">${svgIcon('guild')}<div><span>${members.length}</span><small>Members</small></div></div><div class="stat-tile">${svgIcon('timer')}<div><span>${minutes}</span><small>Minutes Together</small></div></div><div class="stat-tile">${svgIcon('streak')}<div><span>${(g?.sessionHistory||[]).length}</span><small>Sessions Finished</small></div></div><div class="stat-tile">${svgIcon('calendar')}<div><span>${(g?.sharedCalendar||[]).length}</span><small>Guild Events</small></div></div></div></div></section><section class="panel" style="margin-top:16px" data-tour="guild-members"><div class="section-head"><h3>Member Overview</h3><span class="status-pill">Live Summary</span></div><div class="deck-grid">${members.map(mem=>`<div class="deck-card">${renderMiniAvatar(mem.avatar)}<h3>${esc(mem.displayName)}</h3><p>Level ${mem.level} · ${mem.streak}-Day Streak</p><p class="helper">${mem.totalQae} QAE Questions · ${mem.totalMistakes||0} Mistakes · ${mem.completedDays||0} Completed Days</p></div>`).join('')||'<p class="helper">No members yet.</p>'}</div></section><section class="panel" style="margin-top:16px"><h3>Session History</h3><div class="list">${(g?.sessionHistory||[]).slice(0,12).map(s=>`<div class="list-card"><h4>${esc(s.title)}</h4><p>${formatDate(s.date)} · ${s.minutes} Minutes · Completed ${new Date(s.completedAt).toLocaleString()}</p></div>`).join('')||'<p class="helper">No completed guild sessions yet.</p>'}</div></section>`;
  if(g){ $('#copyJoinBtn').onclick=()=>navigator.clipboard?.writeText(`Group ID: ${g.id}\nJoin Code: ${g.joinCode}`).then(()=>toast('Join Info Copied.')); $('#leaveGuildBtn').onclick=leaveGuildFlow; $('#saveGuildBtn').onclick=saveGuildSettings; $('#guildIcon').onchange=handleGuildIcon; } else { $('#createGuildBtn').onclick=createGuildFlow; $('#joinGuildBtn').onclick=joinGuildFlow; }
}
async function createGuildFlow(){ const name=$('#newGuildName').value.trim()||'New Study Guild'; const group=defaultGroup(state.user.uid,state.profile,name); await createGroup(group); state.profile.activeGroupId=group.id; state.profile.groups=[...new Set([...(state.profile.groups||[]),group.id])]; state.group=group; await saveAll({group:true}); renderApp(); }
async function joinGuildFlow(){ const id=$('#joinGroupId').value.trim(), code=$('#joinCode').value.trim(); if(!id||!code)return toast('Enter Group ID And Join Code.','warn'); const g=await joinGroup(id,code,state.profile); state.profile.activeGroupId=id; state.profile.groups=[...new Set([...(state.profile.groups||[]),id])]; state.group=g; await saveAll({group:true}); attachGroup(id); renderApp(); }
async function leaveGuildFlow(){ if(!confirm('Leave This Guild? Your personal profile stays intact.'))return; await leaveGroup(state.group.id,state.profile); state.profile.activeGroupId=null; state.group=null; state.groupAttached=null; await saveAll(); renderApp(); }
async function saveGuildSettings(){ state.group.name=$('#guildName').value.trim()||state.group.name; await saveAll({group:true}); toast('Guild Settings Saved.'); renderApp(); }
function handleGuildIcon(e){ const file=e.target.files?.[0]; if(!file)return; if(file.size>200000)return toast('Use An Image Under 200 KB.','warn'); const reader=new FileReader(); reader.onload=async()=>{ state.group.iconData=reader.result; await saveAll({group:true}); toast('Guild Icon Saved.'); }; reader.readAsDataURL(file); }

function renderCalendar(m){
  const p=state.profile; if(!state.calendarMonth) state.calendarMonth=todayISO(p).slice(0,7); const [year,month]=state.calendarMonth.split('-').map(Number); const first=new Date(year,month-1,1); const start=new Date(first); start.setDate(1-first.getDay()); const days=[]; for(let i=0;i<42;i++){ const d=new Date(start); d.setDate(start.getDate()+i); days.push(d.toISOString().slice(0,10)); }
  const events=allEvents();
  m.innerHTML=`<section class="calendar-shell"><div class="panel" data-tour="calendar-view"><div class="section-head"><div><p class="eyebrow">Calendar</p><h2>${first.toLocaleDateString([], {month:'long',year:'numeric'})}</h2><p class="helper">Personal events are violet, guild events are blue, and shared/both events are green.</p></div><div class="button-row"><button class="secondary-button" id="prevMonthBtn">Previous</button><button class="secondary-button" id="nextMonthBtn">Next</button><button class="primary-button" id="newEventBtn">Create Event</button></div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<strong class="muted">${d}</strong>`).join('')}${days.map(d=>calendarDay(d,month,events)).join('')}</div></div><aside class="panel"><p class="eyebrow">Quick Actions</p><h3>Calendar Tools</h3><p class="helper">Create an event, generate a lesson plan, then download an Outlook-friendly ICS file.</p><button class="secondary-button full" id="downloadRecurringBtn">Download Weekday Study ICS</button><h3>Upcoming</h3><div class="list">${events.filter(e=>e.date>=todayISO(p)).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,8).map(e=>`<div class="list-card"><h4>${esc(e.title)}</h4><p>${formatDate(e.date)} · ${esc(titleCase(e.scope||'Personal'))}</p></div>`).join('')||'<p class="helper">No upcoming events yet.</p>'}</div></aside></section>`;
  $('#prevMonthBtn').onclick=()=>{ const d=new Date(`${state.calendarMonth}-01T12:00:00`); d.setMonth(d.getMonth()-1); state.calendarMonth=d.toISOString().slice(0,7); renderApp();}; $('#nextMonthBtn').onclick=()=>{ const d=new Date(`${state.calendarMonth}-01T12:00:00`); d.setMonth(d.getMonth()+1); state.calendarMonth=d.toISOString().slice(0,7); renderApp();}; $('#newEventBtn').onclick=()=>openEventModal(); $('#downloadRecurringBtn').onclick=downloadRecurring;
  $$('.calendar-day').forEach(day=>day.ondblclick=()=>openEventModal({date:day.dataset.date})); $$('.event-pill').forEach(e=>e.onclick=ev=>{ev.stopPropagation(); openEventModal(allEvents().find(x=>x.id===e.dataset.id));});
}
function allEvents(){ const personal=(state.profile.progress.calendarEvents||[]).map(e=>({...e,origin:'personal'})); const guild=(state.group?.sharedCalendar||[]).map(e=>({...e,origin:'guild'})); const map=new Map(); [...personal,...guild].forEach(e=>map.set(e.id,e)); return [...map.values()]; }
function calendarDay(d,month,events){ const out=new Date(`${d}T12:00:00`).getMonth()+1!==month; return `<div class="calendar-day ${out?'out':''}" data-date="${d}"><strong>${new Date(`${d}T12:00:00`).getDate()}</strong>${events.filter(e=>e.date===d).map(e=>`<button class="event-pill event-${e.scope||'personal'}" data-id="${e.id}">${esc(e.title)}</button>`).join('')}</div>`; }
function openEventModal(existing={}){ const e=existing.id?existing:{id:null,title:'',date:existing.date||todayISO(state.profile),time:state.profile.studyPlan.sessionTime,duration:state.profile.studyPlan.sessionDuration,scope:'personal',description:'',plan:false}; modal(existing.id?'Edit Event':'Create Event',`<label>Title<input id="eventTitle" value="${escAttr(e.title||'')}"></label><div class="three-col"><label>Date<input type="date" id="eventDate" value="${e.date}"></label><label>Time<input type="time" id="eventTime" value="${e.time||'07:00'}"></label><label>Duration Minutes<input type="number" id="eventDuration" min="15" max="240" value="${e.duration||60}"></label></div><label>Scope<select id="eventScope"><option value="personal">Personal</option><option value="guild">Guild</option><option value="both">Both</option></select></label><label>Description<textarea id="eventDescription">${esc(e.description||'')}</textarea></label><label class="check-row"><input type="checkbox" id="eventPlan" ${e.plan?'checked':''}><div><strong>Plan Me A Study Session</strong><small>Add lesson tasks to the calendar event and show it on the roadmap.</small></div></label>`,async()=>{ const dur=Number($('#eventDuration').value); if(!$('#eventTitle').value.trim()||dur<15)return toast('Add A Title And Valid Duration.','error'); const obj={id:e.id||crypto.randomUUID(),title:$('#eventTitle').value.trim(),date:$('#eventDate').value,time:$('#eventTime').value,duration:dur,scope:$('#eventScope').value,description:$('#eventDescription').value,plan:$('#eventPlan').checked,updatedAt:new Date().toISOString()}; if(obj.plan){ obj.lessonTasks=['Review Weakest Domain',`Complete A ${Math.max(10,Math.round(dur/4))}-Question QAE Block`,'Update Mistake Forge','Add Three Flashcards']; }
    saveCalendarEvent(obj,e); await saveAll({group:true}); renderApp(); },'Save Event', existing.id?`<button class="danger-button" id="deleteEventBtn">Delete Event</button><button class="secondary-button" id="downloadEventBtn">Download ICS</button>`:'');
  setTimeout(()=>{ const scope=$('#eventScope'); if(scope) scope.value=e.scope||'personal'; $('#deleteEventBtn')?.addEventListener('click',async()=>{ if(confirm('Delete This Event?')){ deleteCalendarEvent(e); await saveAll({group:true}); $('.modal-backdrop')?.remove(); renderApp(); }}); $('#downloadEventBtn')?.addEventListener('click',()=>downloadEvent(e)); },0); }
function saveCalendarEvent(obj,old={}){ const shouldPersonal=obj.scope==='personal'||obj.scope==='both', shouldGuild=obj.scope==='guild'||obj.scope==='both'; state.profile.progress.calendarEvents=state.profile.progress.calendarEvents.filter(x=>x.id!==obj.id); if(state.group) state.group.sharedCalendar=(state.group.sharedCalendar||[]).filter(x=>x.id!==obj.id); if(shouldPersonal) state.profile.progress.calendarEvents.unshift(obj); if(shouldGuild&&state.group) state.group.sharedCalendar.unshift(obj); if(obj.plan){ state.profile.progress.weekendLogs=state.profile.progress.weekendLogs.filter(x=>x.id!==obj.id); state.profile.progress.weekendLogs.push({...obj,tasks:obj.lessonTasks}); } }
function deleteCalendarEvent(e){ state.profile.progress.calendarEvents=state.profile.progress.calendarEvents.filter(x=>x.id!==e.id); if(state.group)state.group.sharedCalendar=(state.group.sharedCalendar||[]).filter(x=>x.id!==e.id); state.profile.progress.weekendLogs=state.profile.progress.weekendLogs.filter(x=>x.id!==e.id); }
function downloadEvent(e){ downloadIcs({title:e.title,description:e.description,startDate:e.date,time:e.time,durationMinutes:e.duration||60,attendees:[]}); }
function downloadRecurring(){ downloadIcs({title:'ControlQuest Study Session',description:'Recurring CISA Study Session',startDate:state.profile.studyPlan.startDate,time:state.profile.studyPlan.sessionTime,durationMinutes:state.profile.studyPlan.sessionDuration,recurrence:recurrenceRuleForDays(state.profile.studyPlan.sessionDays,state.profile.studyPlan.examDate),attendees:[]}); }

function renderNotes(m){
  const notes=getNotes(state.noteScope);
  m.innerHTML=`<section class="note-grid"><div class="panel" data-tour="notebook-list"><p class="eyebrow">Notebook</p><h2>${state.noteScope} Notes</h2><div class="scope-tabs">${['Personal','Guild','Public'].map(s=>`<button class="secondary-button small ${state.noteScope===s?'active':''}" data-note-scope="${s}">${s}</button>`).join('')}</div><div class="notes-list">${notes.map(n=>`<button class="note-card" data-note-id="${n.id}"><h4>${esc(n.title)}</h4><p>${esc((n.body||'').slice(0,110))}</p><small>${new Date(n.createdAt||Date.now()).toLocaleString()}</small></button>`).join('')||'<p class="helper">No notes in this notebook yet.</p>'}</div></div><div class="panel" data-tour="note-editor"><div class="section-head"><div><p class="eyebrow">Note Editor</p><h2>Create Or Edit Notes</h2></div><div class="button-row"><button class="secondary-button" id="exportNotesBtn">Export Notes</button></div></div><label>Title<input id="noteTitle" placeholder="Example: BCP / DR Key Differences"></label><label>Scope<select id="noteScopeInput"><option>Personal</option><option>Guild</option><option>Public</option></select></label><label>Body<textarea id="noteBody" placeholder="Capture notes, diagrams, links, and takeaways."></textarea></label><div class="button-row"><button class="primary-button" id="saveNoteBtn">Save Note</button><button class="secondary-button" id="clearNoteBtn">Clear</button><button class="danger-button" id="deleteNoteBtn" style="display:none">Delete</button></div></div></section>`;
  $$('[data-note-scope]').forEach(b=>b.onclick=()=>{state.noteScope=b.dataset.noteScope;renderApp();}); let editing=null; $$('.note-card').forEach(b=>b.onclick=()=>{ const n=getNotes(state.noteScope).find(x=>x.id===b.dataset.noteId); if(!n)return; editing=n; $('#noteTitle').value=n.title; $('#noteScopeInput').value=n.scope||state.noteScope; $('#noteBody').value=n.body; $('#deleteNoteBtn').style.display='inline-flex'; }); $('#saveNoteBtn').onclick=async()=>{ const n={id:editing?.id||crypto.randomUUID(),title:$('#noteTitle').value||'Untitled Note',scope:$('#noteScopeInput').value,body:$('#noteBody').value,createdAt:editing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),author:state.profile.displayName}; saveNoteObj(n,editing); awardWithPop({xp:editing?0:25,coins:editing?0:8,reason:editing?'Note Updated':'Notebook Note Created',source:'Notebook'}); await saveAll({group:true}); renderApp(); }; $('#clearNoteBtn').onclick=()=>{editing=null; $('#noteTitle').value='';$('#noteBody').value='';$('#deleteNoteBtn').style.display='none';}; $('#deleteNoteBtn').onclick=async()=>{ if(!editing||!confirm('Delete This Note?'))return; deleteNoteObj(editing); await saveAll({group:true}); renderApp(); }; $('#exportNotesBtn').onclick=exportNotes;
}
function getNotes(scope){ if(scope==='Guild')return state.group?.notes||[]; if(scope==='Public')return [...(state.profile.progress.notes||[]).filter(n=>n.scope==='Public'),...(state.group?.notes||[]).filter(n=>n.scope==='Public')]; return state.profile.progress.notes.filter(n=>!n.scope||n.scope==='Personal'); }
function addNoteObject(n){ saveNoteObj({id:crypto.randomUUID(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),author:state.profile.displayName,...n},null); }
function saveNoteObj(n,old){ if(n.scope==='Guild'&&state.group){ state.group.notes=state.group.notes||[]; const i=state.group.notes.findIndex(x=>x.id===n.id); i>=0?state.group.notes[i]=n:state.group.notes.unshift(n); } else { state.profile.progress.notes=state.profile.progress.notes||[]; const i=state.profile.progress.notes.findIndex(x=>x.id===n.id); i>=0?state.profile.progress.notes[i]=n:state.profile.progress.notes.unshift(n); } }
function deleteNoteObj(n){ state.profile.progress.notes=state.profile.progress.notes.filter(x=>x.id!==n.id); if(state.group) state.group.notes=(state.group.notes||[]).filter(x=>x.id!==n.id); }
function exportNotes(){ const notes=getNotes(state.noteScope); const md=notes.map(n=>`# ${n.title}\n\n${n.body}\n`).join('\n---\n'); downloadText(`controlquest-${state.noteScope.toLowerCase()}-notes.md`,md); const html=`<html><body>${notes.map(n=>`<h1>${esc(n.title)}</h1><p>${esc(n.body).replaceAll('\n','<br>')}</p>`).join('<hr>')}</body></html>`; downloadBlob(`controlquest-${state.noteScope.toLowerCase()}-notes.doc`,html,'application/msword'); }

function renderRewards(m){
  const p=state.profile,lvl=levelFromXp(p.stats.xp||0);
  m.innerHTML=`<section class="two-col"><div class="panel" data-tour="rewards-progress"><p class="eyebrow">XP And Audit Coins</p><h2>Reward Activity</h2><div class="grid-4"><div class="stat-tile">${svgIcon('xp')}<div><span>${p.stats.xp||0}</span><small>Total XP</small></div></div><div class="stat-tile">${svgIcon('coin')}<div><span>${p.stats.coins||0}</span><small>Audit Coins</small></div></div><div class="stat-tile">${svgIcon('streak')}<div><span>${p.stats.streak||0}</span><small>Current Streak</small></div></div><div class="stat-tile">${svgIcon('freeze')}<div><span>${p.stats.streakFreezes||0}</span><small>Auto Freezes</small></div></div></div><div class="progress"><span style="width:${lvl.progress}%"></span></div><p class="helper">Level ${lvl.level}. Next Level At ${lvl.nextXp} XP.</p><div class="activity-mini">${(p.progress.xpLog||[]).map(activityRow).join('')||'<p class="helper">No activity yet.</p>'}</div></div><div class="panel" data-tour="chests-shop"><p class="eyebrow">Quest Shop</p><h2>Shop And Chests</h2><div class="shop-grid">${SHOP_ITEMS.map(renderShopItem).join('')}</div><h3>Treasure Chests</h3><div class="shop-grid">${(p.progress.chests||[]).filter(c=>!c.opened).map(c=>`<div class="shop-card"><span class="icon-art icon-coin">${svgIcon('chest')}</span><h3>${titleCase(c.type)} Chest</h3><p>${esc(c.reason||'Quest Reward')}</p><button class="primary-button open-chest" data-id="${c.id}">Open Chest</button></div>`).join('')||'<p class="helper">No unopened chests right now.</p>'}</div></div></section><section class="panel" style="margin-top:16px" data-tour="avatar-closet"><div class="section-head"><div><p class="eyebrow">Avatar Closet</p><h2>Customize Your Avatar</h2><p class="helper">Unlocked items can be equipped. Locked items can be purchased with Audit Coins after confirmation.</p></div><div class="avatar-preview">${renderAvatar(p)}</div></div>${Object.keys(AVATAR_ITEMS).map(type=>`<h3>${titleCase(type)}</h3><div class="avatar-grid">${AVATAR_ITEMS[type].map(item=>renderAvatarItem(type,item)).join('')}</div>`).join('')}</section>`;
  $$('.buy-shop').forEach(b=>b.onclick=()=>purchaseShopItem(b.dataset.id)); $$('.open-chest').forEach(b=>b.onclick=()=>openChestFlow(b.dataset.id)); $$('.avatar-item button').forEach(b=>b.onclick=()=>avatarAction(b.dataset.type,b.dataset.id));
}
function renderShopItem(item){ return `<div class="shop-card"><span class="icon-art">${svgIcon(item.icon||'shop')}</span><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><strong>${item.cost} Audit Coins</strong><button class="primary-button buy-shop" data-id="${item.id}">Buy</button></div>`; }
function renderAvatarItem(type,item){ const owned=state.profile.avatar.owned?.includes(item.id), active=state.profile.avatar[type]===item.id, unlocked=isAvatarItemUnlocked(state.profile,type,item.id); return `<div class="avatar-item ${active?'active':''}"><h4>${esc(item.label)}</h4><p class="helper">Unlock: ${esc(item.unlock)} · Cost: ${item.cost}</p><button class="${owned||unlocked?'secondary-button':'primary-button'}" data-type="${type}" data-id="${escAttr(item.id)}">${active?'Equipped':owned||unlocked?'Equip':'Buy'}</button></div>`; }
async function purchaseShopItem(id){ const item=SHOP_ITEMS.find(i=>i.id===id); if(!item)return; if(!confirm(`Buy ${item.title} For ${item.cost} Audit Coins?`))return; try{buyShopItem(state.profile,id); awardWithPop({xp:0,coins:0,reason:`Purchased: ${item.title}`,source:'Quest Shop'}); await saveAll(); renderApp();}catch(e){toast(friendly(e),'error')} }
async function openChestFlow(id){ const reward=openChest(state.profile,id); if(!reward)return; showLevelModal('Chest Opened',`You Earned ${reward.xp} XP And ${reward.coins} Audit Coins.`); await saveAll(); renderApp(); }
async function avatarAction(type,id){ const item=AVATAR_ITEMS[type].find(i=>i.id===id); if(!item)return; if(!state.profile.avatar.owned?.includes(id)&&!isAvatarItemUnlocked(state.profile,type,id)){ if(!confirm(`Buy ${item.label} For ${item.cost} Audit Coins?`))return; } try{buyAvatarItem(state.profile,type,id); await saveAll(); renderApp();}catch(e){toast(friendly(e),'error')} }

function renderProfile(m){
  const p=state.profile;
  m.innerHTML=`<section class="two-col"><div class="panel" data-tour="profile-settings"><p class="eyebrow">Profile Settings</p><h2>Your Preferences</h2><label>Display Name<input id="displayName" value="${escAttr(p.displayName)}"></label><label>Theme<select id="prefTheme"><option value="dark">Dark</option><option value="light">Light</option></select></label><label>Timezone<input id="prefTimezone" value="${escAttr(p.preferences.timezone)}"></label><label>Exam Date<input type="date" id="profileExam" value="${p.studyPlan.examDate}"></label><label>Daily QAE Goal<input type="number" id="profileQaeGoal" min="1" max="150" value="${p.studyPlan.dailyQaeGoal}"></label><div class="button-row"><button class="primary-button" id="saveProfileBtn">Save Settings</button><button class="secondary-button" id="redoOnboardingBtn">Redo Onboarding</button><button class="secondary-button" id="fullTourBtn">Full Website Tour</button></div></div><div class="panel"><p class="eyebrow">Safety Zone</p><h2>Testing And Data</h2><p class="helper">Reset creates a backup inside your profile first. Delete archives your profile to deletedProfiles before removal.</p><div class="button-row"><button class="secondary-button" id="exportBackupBtn">Export JSON Backup</button><button class="danger-button" id="resetProfileBtn">Reset Testing Stats</button><button class="danger-button" id="deleteProfileBtn">Delete Profile</button></div><h3>Reset Backups</h3><p class="helper">${p.progress.resetBackups?.length||0} reset backup(s) stored in your profile.</p></div></section>`;
  $('#prefTheme').value=p.preferences.theme; $('#saveProfileBtn').onclick=saveProfileSettings; $('#redoOnboardingBtn').onclick=showOnboardingWizard; $('#fullTourBtn').onclick=()=>showFullTour(); $('#exportBackupBtn').onclick=()=>exportProfileBackup(p); $('#resetProfileBtn').onclick=resetProfileFlow; $('#deleteProfileBtn').onclick=deleteProfileFlow;
}
async function saveProfileSettings(){ const q=validateNumber('#profileQaeGoal',1,150,'Daily QAE Goal Must Be 1–150.'); if(!q)return; state.profile.displayName=$('#displayName').value.trim()||state.profile.displayName; state.profile.preferences.theme=$('#prefTheme').value; state.profile.preferences.timezone=$('#prefTimezone').value.trim()||state.profile.preferences.timezone; state.profile.studyPlan.examDate=$('#profileExam').value; state.profile.studyPlan.dailyQaeGoal=q; applyTheme(); await saveAll(); renderApp(); }
async function resetProfileFlow(){ if(!confirm('Reset Testing Stats? This creates a backup first.'))return; if(!confirm('Second Warning: XP, Coins, Logs, Roadmap Status, Notes, Decks, Homework, And Chests Will Reset. Continue?'))return; const typed=prompt('Type RESET PROFILE to confirm.'); if(typed!=='RESET PROFILE')return; state.profile=resetProfileForTesting(state.profile); await saveAll(); toast('Profile Reset With Backup.'); renderApp(); }
async function deleteProfileFlow(){ if(!confirm('Delete Profile? A Firestore Backup Will Be Created First.'))return; if(!confirm('Second Warning: Active Profile Data Will Be Removed.'))return; const typed=prompt('Type DELETE PROFILE to continue.'); if(typed!=='DELETE PROFILE')return; try{const id=await archiveAndDeleteProfile(state.profile,'',false);toast(`Profile Archived And Deleted. Backup ${id}`);await logout();}catch(e){toast(friendly(e),'error')} }

function showOnboardingWizard(){
  const p=state.profile;
  modal('Set Up Your Quest',`<p class="helper">This sets the basics so ControlQuest can build a useful roadmap and streak system.</p><label>Preferred Theme<select id="obTheme"><option value="dark">Dark</option><option value="light">Light</option></select></label><label>Timezone<input id="obTimezone" value="${escAttr(p.preferences.timezone)}"></label><div class="two-col"><label>Exam Date<input type="date" id="obExam" value="${p.studyPlan.examDate}"></label><label>Start Date<input type="date" id="obStart" value="${p.studyPlan.startDate}"></label></div><div class="two-col"><label>Normal Study Time<input type="time" id="obTime" value="${p.studyPlan.sessionTime}"></label><label>Session Length Minutes<input type="number" id="obDuration" min="15" max="240" value="${p.studyPlan.sessionDuration}"></label></div><label>Daily QAE Goal<input type="number" id="obQae" min="1" max="150" value="${p.studyPlan.dailyQaeGoal}"></label>`,async()=>{ const dur=Number($('#obDuration').value), q=Number($('#obQae').value); if(dur<15||dur>240||q<1||q>150)return toast('Check Duration And QAE Goal.','error'); p.preferences.theme=$('#obTheme').value; p.preferences.timezone=$('#obTimezone').value; p.studyPlan.examDate=$('#obExam').value; p.studyPlan.startDate=$('#obStart').value; p.studyPlan.sessionTime=$('#obTime').value; p.studyPlan.sessionDuration=dur; p.studyPlan.dailyQaeGoal=q; p.onboarding.completed=true; applyTheme(); await saveAll(); renderApp(); showFullTour(); },'Save And Start Tour'); setTimeout(()=>{$('#obTheme').value=p.preferences.theme},0);
}
function showFullTour(){ const views=['home','room','plan','practice','tools','guild','calendar','notes','rewards','profile']; let i=0; const next=()=>{ if(i>=views.length)return; state.activeView=views[i++]; renderApp(); setTimeout(()=>showPageTour(state.activeView,next),120); }; next(); }
function showPageTour(view=state.activeView, after=null){ const steps={home:[['home-hero','This Is Today’s Mission. Start here to see what you should focus on today.'],['daily-quests','Daily Quests Are The Streak Gate. Complete all three to protect your streak.'],['xp-box','This box shows XP, coins, level progress, and your most recent activity.']], room:[['room-timer','The timer syncs for everyone in your guild and updates every second.'],['session-flow','These shared checklist items persist live during the study session.'],['room-notes','Shared notes can be saved into the Notebook after the session.']], plan:[['plan-settings','Set your start date, exam date, QAE target, and timezone here.'],['roadmap-weeks','Click any day card to open its lesson tasks, links, and details.']], practice:[['qae-log','Log official QAE blocks here. The site validates the numbers and charts your trend.'],['mistake-forge','Turn misses into repeatable CISA logic.']], tools:[['memory-decks','Study flashcards by Public, Guild, or Personal deck scope.'],['arcade','Play games for extra XP and coins.']], guild:[['guild-setup','Create, join, or customize your study guild here.'],['guild-members','See high-level member progress without exposing private notes.']], calendar:[['calendar-view','Use the month calendar to add, edit, delete, or download events.']], notes:[['notebook-list','Switch between Personal, Guild, and Public notes.'],['note-editor','Create, edit, export, or delete notes here.']], rewards:[['rewards-progress','Track XP, coins, streaks, freezes, and activity history.'],['chests-shop','Buy boosts, freezes, and chests with Audit Coins.'],['avatar-closet','Customize the avatar with unlockable or purchasable items.']], profile:[['profile-settings','Customize profile, theme, timezone, exam date, and onboarding.']] }[view]||[]; if(!steps.length){toast('No Page Tour Available Yet.');return;} let idx=0; const step=()=>{ if(idx>=steps.length){cleanupTour(); if(after)after(); return;} cleanupTour(); const [sel,text]=steps[idx++], el=document.querySelector(`[data-tour="${sel}"]`); if(!el){step();return;} const r=el.getBoundingClientRect(); const hi=document.createElement('div'); hi.className='tour-highlight'; hi.style.left=`${Math.max(8,r.left-6)}px`; hi.style.top=`${Math.max(8,r.top-6)}px`; hi.style.width=`${Math.min(innerWidth-16,r.width+12)}px`; hi.style.height=`${Math.min(innerHeight-16,r.height+12)}px`; const card=document.createElement('div'); card.className='tour-card'; const left=Math.min(innerWidth-400,Math.max(16,r.left)); const top=(r.bottom+16<innerHeight-180)?r.bottom+16:Math.max(16,r.top-190); card.style.left=`${left}px`; card.style.top=`${top}px`; card.innerHTML=`<p class="eyebrow">${pageTitle()} Help</p><h3>Step ${idx} / ${steps.length}</h3><p>${esc(text)}</p><div class="button-row"><button class="secondary-button" data-tour-close>Close</button><button class="primary-button" data-tour-next>${idx===steps.length?'Finish':'Next'}</button></div>`; document.body.append(hi,card); $('[data-tour-close]',card).onclick=()=>{cleanupTour(); if(after)after();}; $('[data-tour-next]',card).onclick=step; el.scrollIntoView({block:'center',behavior:'smooth'}); }; step(); }
function cleanupTour(){ $$('.tour-highlight,.tour-card').forEach(x=>x.remove()); }

async function saveAll({group=false,quiet=false}={}){ if(!state.profile)return; try{ await saveProfile(state.profile); if(state.profile.activeGroupId) await updateMemberSummary(state.profile.activeGroupId,state.profile); if(group&&state.group) await saveGroup(state.group); if(!quiet) toast('Saved.'); }catch(e){ toast(friendly(e),'error'); } }
function awardWithPop(opts){ const before=levelFromXp(state.profile.stats.xp||0).level; const result=award(state.profile,opts); const after=levelFromXp(state.profile.stats.xp||0).level; showXpPop(result.xp,result.coins,opts.reason); if(after>before) showLevelModal(`Level ${after} Reached`,levelUnlockText(after)); return result; }
function maybeChest(type,reason,chance){ if(Math.random()<chance){ state.profile.progress.chests.unshift({id:crypto.randomUUID(),type,reason,opened:false,at:new Date().toISOString()}); showLevelModal('Treasure Chest Earned',`You earned a ${titleCase(type)} Chest. Open it in Rewards.`); } }
function showXpPop(xp,coins,reason){ const el=document.createElement('div'); el.className='xp-pop'; el.innerHTML=`+${xp||0} XP · +${coins||0} Coins<br><small>${esc(reason||'Quest Complete')}</small>`; document.body.appendChild(el); setTimeout(()=>el.remove(),1700); confetti(16); }
function showLevelModal(title,msg){ confetti(48); modal(title,`<div class="level-pop">${renderAvatar(state.profile)}<h3>${esc(msg)}</h3></div>`,()=>{},'Celebrate'); }
function levelUnlockText(level){ return `New level unlocked. Check Rewards for avatar items, shop upgrades, and bonus motivation.`; }
function celebrate(msg){ toast(msg); confetti(24); }
function confetti(n=24){ for(let i=0;i<n;i++){const el=document.createElement('i');el.className='confetti';el.style.left=Math.random()*100+'vw';el.style.background=`hsl(${Math.random()*360},80%,60%)`;el.style.animationDelay=Math.random()*.25+'s';document.body.appendChild(el);setTimeout(()=>el.remove(),1700);} }
function modal(title,body,onOk,ok='Save',extra=''){ const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal-card"><h2>${esc(title)}</h2>${body}<div class="button-row">${extra}<button class="secondary-button" data-cancel>Cancel</button><button class="primary-button" data-ok>${ok}</button></div></div>`;document.body.appendChild(wrap);wrap.querySelector('[data-cancel]').onclick=()=>wrap.remove();wrap.querySelector('[data-ok]').onclick=async()=>{await onOk?.();wrap.remove();}; }
function toast(message,type='success'){ let layer=$('#toastLayer'); if(!layer){layer=document.createElement('div');layer.id='toastLayer';layer.className='toast-layer';document.body.appendChild(layer);} const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;layer.appendChild(el);setTimeout(()=>el.remove(),3600); }
function applyTheme(){document.documentElement.dataset.theme=state.profile?.preferences?.theme||'dark';}
function bindGo(){ $$('[data-go]').forEach(b=>b.onclick=()=>{state.activeView=b.dataset.go;renderApp();}); }
function validateNumber(sel,min,max,msg){ const el=$(sel); const n=Number(el.value); clearFieldError(el); if(!Number.isFinite(n)||n<min||n>max){ fieldError(sel,msg); return false; } return n; }
function fieldError(sel,msg){ const el=$(sel); el?.classList.add('input-error'); const e=document.createElement('div'); e.className='field-error'; e.textContent=msg; el?.after(e); toast(msg,'error'); return false; }
function clearFieldError(el){ if(!el)return; el.classList.remove('input-error'); el.parentElement?.querySelectorAll('.field-error').forEach(x=>x.remove()); }
function timerSeconds(s){ if(!s)return 0; let sec=s.accumulatedSeconds||0; if(s.active&&s.startedAt)sec+=Math.floor((Date.now()-new Date(s.startedAt).getTime())/1000); return sec; }
function startTimerTicker(){ stopTimer(); state.timerTick=setInterval(()=>{const s=state.group?.liveSession;if(!s)return; const total=(s.durationMinutes||60)*60, elapsed=timerSeconds(s), rem=Math.max(0,total-elapsed), pct=Math.min(100,Math.round(elapsed/Math.max(1,total)*100)); const text=$('#timerText'), orb=$('#timerOrb'), bar=$('#timerBar'); if(text)text.textContent=fmtTime(rem); if(orb)orb.style.setProperty('--timer-progress',pct+'%'); if(bar)bar.style.width=pct+'%';},1000); }
function stopTimer(){ if(state.timerTick)clearInterval(state.timerTick); }
function fmtTime(s){const m=Math.floor(s/60),sec=s%60;return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;}
function renderMiniAvatar(a){return renderAvatar({avatar:a||{},stats:{},progress:{}},'tiny');}
function appIcon(name){return `<span class="app-icon ${name}"></span>`;}
function svgIcon(name){ const paths={xp:'<path d="M32 6l8 17h18L44 35l5 19-17-10-17 10 5-19L6 23h18z" fill="white"/>',coin:'<circle cx="32" cy="32" r="24" fill="white" opacity=".92"/><path d="M24 26c2-5 14-5 16 0 2 6-16 4-14 11 2 6 15 5 17-1M32 17v30" stroke="#ff9f1c" stroke-width="5" stroke-linecap="round" fill="none"/>',freeze:'<path d="M32 8v48M12 20l40 24M52 20L12 44M20 12l24 40M44 12L20 52" stroke="white" stroke-width="5" stroke-linecap="round"/>',streak:'<path d="M34 58c12-3 19-12 19-24 0-13-9-21-15-28 1 13-6 15-12 24-1-6-4-10-8-13 0 7-7 13-7 23 0 11 10 19 23 18Z" fill="white"/>',roadmap:'<path d="M13 14h38v9H13zm0 14h28v9H13zm0 14h38v9H13z" fill="white"/>',qae:'<circle cx="32" cy="32" r="24" fill="none" stroke="white" stroke-width="6"/><path d="M23 32l6 6 13-15" stroke="white" stroke-width="6" fill="none" stroke-linecap="round"/>',target:'<circle cx="32" cy="32" r="24" fill="none" stroke="white" stroke-width="5"/><circle cx="32" cy="32" r="12" fill="none" stroke="white" stroke-width="5"/><circle cx="32" cy="32" r="4" fill="white"/>',cards:'<rect x="14" y="18" width="28" height="34" rx="5" fill="white"/><rect x="24" y="12" width="28" height="34" rx="5" fill="white" opacity=".7"/>',forge:'<path d="M18 45h28l4 9H14zM23 15h18v30H23z" fill="white"/><path d="M16 26h32" stroke="#7c4dff" stroke-width="6"/>',chevron:'<path d="M18 24l14 16 14-16" fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round"/>',guild:'<path d="M32 9l22 13v22L32 56 10 44V22z" fill="white"/><circle cx="32" cy="29" r="8" fill="#7c4dff"/><path d="M20 44c5-10 19-10 24 0" fill="#7c4dff"/>',timer:'<circle cx="32" cy="34" r="20" fill="none" stroke="white" stroke-width="6"/><path d="M32 34V22M32 34l9 6M24 8h16" stroke="white" stroke-width="6" stroke-linecap="round"/>',calendar:'<rect x="12" y="16" width="40" height="36" rx="5" fill="white"/><path d="M12 26h40" stroke="#7c4dff" stroke-width="5"/><path d="M22 10v12M42 10v12" stroke="white" stroke-width="5" stroke-linecap="round"/>',homework:'<path d="M16 10h28l8 8v36H16z" fill="white"/><path d="M24 30h18M24 39h18" stroke="#7c4dff" stroke-width="5" stroke-linecap="round"/>',notebook:'<rect x="16" y="10" width="36" height="44" rx="5" fill="white"/><path d="M24 22h18M24 32h18M24 42h10" stroke="#7c4dff" stroke-width="5" stroke-linecap="round"/>',arcade:'<rect x="12" y="22" width="40" height="28" rx="10" fill="white"/><path d="M22 36h12M28 30v12" stroke="#7c4dff" stroke-width="5" stroke-linecap="round"/><circle cx="42" cy="34" r="3" fill="#7c4dff"/><circle cx="48" cy="40" r="3" fill="#7c4dff"/>',voice:'<rect x="25" y="10" width="14" height="30" rx="7" fill="white"/><path d="M16 31c0 10 7 18 16 18s16-8 16-18M32 49v8" stroke="white" stroke-width="5" stroke-linecap="round"/>',shop:'<path d="M14 24h36v28H14z" fill="white"/><path d="M18 24c1-10 8-16 14-16s13 6 14 16" fill="none" stroke="white" stroke-width="6"/>',chest:'<rect x="10" y="24" width="44" height="28" rx="6" fill="white"/><path d="M14 24c1-9 8-14 18-14s17 5 18 14" fill="none" stroke="white" stroke-width="6"/><rect x="27" y="30" width="10" height="12" rx="2" fill="#7c4dff"/>',boost:'<path d="M34 6L12 36h17l-4 22 27-34H36z" fill="white"/>',menu:'<path d="M12 20h40M12 32h40M12 44h40" stroke="white" stroke-width="6" stroke-linecap="round"/>'}; return `<svg viewBox="0 0 64 64" aria-hidden="true">${paths[name]||paths.xp}</svg>`; }
function icon(name){return appIcon(name);}
function titleCase(s=''){ return String(s).replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase()); }
function esc(s=''){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));} function escAttr(s=''){return esc(s).replace(/'/g,'&#39;');} function friendly(e){return e?.message||String(e);} function pick(a){return a[Math.floor(Math.random()*a.length)];} function shuffle(a){return a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);}
function downloadText(filename,text){downloadBlob(filename,text,'text/plain');} function downloadBlob(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
